python3 - <<'EOF'
p='src/transport/ws/validation.ts'
s=open(p).read()
s=s.replace("import type {IncomingMessage} from '../../types/messages.js';","import type {IncomingMessage} from '../../types/messages.js';\nimport type {SessionCursor} from '../../types/sessionStore.js';")
s=s.replace("const MAX_CONTENT_LENGTH = 10000;","const MAX_CONTENT_LENGTH = 10000;\nconst MAX_SESSION_ID_LENGTH = 128;")
s=s.replace("""    case 'ping':
      return validatePingMessage(message);
""","""    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
""")
s+="""
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit, before} = message;
  if (limit !== undefined && !(Number.isInteger(limit) && (limit as number) >= 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (before !== undefined && !isSessionCursor(before)) {
    return {valid: false, error: 'list_sessions before must be {updatedAt, sessionId} with a parseable updatedAt'};
  }
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit === undefined ? {} : {limit: limit as number}),
      ...(before === undefined ? {} : {before: {updatedAt: before.updatedAt, sessionId: before.sessionId}}),
    },
  };
}

function isSessionCursor(value: unknown): value is SessionCursor & {updatedAt: string | number} {
  if (typeof value !== 'object' || value === null) return false;
  const {updatedAt, sessionId} = value as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) return false;
  if (typeof updatedAt === 'string') return !Number.isNaN(Date.parse(updatedAt));
  return typeof updatedAt === 'number' && Number.isFinite(updatedAt);
}
"""
open(p,'w').write(s)
EOF
